if(layer[%1].flying == 0.0, hotspot[%1].resetsize(); calc_flyout_size(%1); );
if(layer[%1].oldscale === null, copy(hotspot[%1].oldscale, hotspot[%1].scale) );
if(layer[%1].oldrx === null, copy(hotspot[%1].oldrx, hotspot[%1].rx) );
if(layer[%1].oldry === null, copy(hotspot[%1].oldry, hotspot[%1].ry) );
if(layer[%1].oldrz === null, copy(hotspot[%1].oldrz, hotspot[%1].rz) );
set(layer[%1].enabled,true);
set(layer[%1].visible,true);
set(layer[%1].align,center);
set(layer[%1].zorder, 999999);
tween(layer[%1].alpha,  1.0);
tween(layer[%1].flying, 1.0);
tween(layer[%1].scale, 0.5);

set(layer[%1].enabled,false);
tween(layer[%1].alpha,  0.0, 0.5, default, set(hotspot[%1].visible,false); );
tween(layer[%1].flying, 0.0);
tween(layer[%1].scale,  get(hotspot[%1].oldscale));
tween(layer[%1].rx,  get(hotspot[%1].oldrx));
tween(layer[%1].ry,  get(hotspot[%1].oldry));
tween(layer[%1].rz,  get(hotspot[%1].oldrz));
